  const possible=possibleRaw===null||possibleRaw===undefined||possibleRaw===''?NaN:Number(possibleRaw);
  const scoreCandidates=[a?.score,a?.pointsEarned,a?.earnedPoints,a?.submissionScore,a?.enteredScore,a?.submission?.score,a?.submission?.entered_score];
  let score=null;for(const v of scoreCandidates){if(v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))){score=Number(v);break}}
