function bindNotebookFileMenu(){const grid=$('#notebookGrid');let hold=null,start=null,suppressKey='';const cancel=()=>{clearTimeout(hold);hold=null;if(start?.button)start.button.classList.remove('holding');start=null};grid.addEventListener('pointerdown',e=>{if(e.button!==0)return;const button=e.target.closest('[data-notebook-key]');if(!button)return;suppressKey='';cancel();start={x:e.clientX,y:e.clientY,button};button.classList.add('holding');hold=setTimeout(()=>{suppressKey=button.dataset.notebookKey;cancel();showNotebookActions(suppressKey).catch(e=>noteStatus(String(e),'error'))},550)});grid.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>10)cancel()});for(const type of ['pointerup','pointercancel','lostpointercapture'])grid.addEventListener(type,cancel);grid.addEventListener('contextmenu',e=>{const b=e.target.closest('[data-notebook-key]');if(b){e.preventDefault();cancel();showNotebookActions(b.dataset.notebookKey).catch(e=>noteStatus(String(e),'error'))}});grid.addEventListener('click',e=>{const options=e.target.closest('[data-notebook-options]'),b=e.target.closest('[data-notebook-key]');if(options){showNotebookActions(options.dataset.notebookOptions).catch(e=>noteStatus(String(e),'error'));return}if(!b)return;if(suppressKey===b.dataset.notebookKey){suppressKey='';e.preventDefault();return}suppressKey='';if(showNotebookTrash)showNotebookActions(b.dataset.notebookKey).catch(e=>noteStatus(String(e),'error'));else openNotebookFile(b.dataset.notebookKey).catch(e=>noteStatus(String(e),'error'))});$('#toggleNotebookTrashBtn').addEventListener('click',()=>{showNotebookTrash=!showNotebookTrash;$('#toggleNotebookTrashBtn').textContent=showNotebookTrash?'Notebooks':'Trash';$('#toggleNotebookTrashBtn').setAttribute('aria-pressed',String(showNotebookTrash));renderNotebookLibrary().catch(()=>{})})}
async function refreshNoteSafety(){const pages=await noteAll('pages'),assets=await noteAll('assets'),pending=pages.filter(p=>p.dirty).length+assets.filter(a=>a.dirty).length,written=pages.filter(pageHasContent);let text=pending?`Saved on this device · ${pending} backup item${pending===1?'':'s'} pending`:(written.length&&written.every(p=>p.cloudBackedAt)?'Saved on this device + backed up to OneDrive':'Saved on this device · connect Microsoft to back up');if(activePageChanged)text='Saving your latest changes…';noteStatus(text,pending||activePageChanged?'dirty':'');$('#librarySafetyStatus').textContent=text;return pending}
