async function recoverNotebookCheckpoint(){await finishNoteInteraction();const list=(await noteAllIndex('revisions','pageKey',activePage.key)).sort((a,b)=>b.at-a.at);if(!list.length){$('#noteActionsStatus').textContent='No local checkpoints for this section yet.';return}const choices=list.slice(0,10),answer=prompt('Recover a copy of a checkpoint (enter its number):\n'+choices.map((r,i)=>`${i+1}. ${new Date(r.at).toLocaleString()} · ${(r.page.strokes||[]).length} strokes`).join('\n'));if(answer===null)return;const r=choices[Number(answer)-1];if(!r)return;const copy=structuredClone(r.page),id=`recovered-${Date.now().toString(36)}`;copy.pageId=id;copy.key=pageKey(copy.courseKey,copy.dateKey,id);copy.order=Math.max(...drawPages.map(p=>p.order||0))+1;copy.conflictCopy=true;copy.dirty=true;copy.rev=(Number(copy.rev)||0)+1;copy.updatedAt=new Date().toISOString();await notePut('pages',copy);await mirrorNoteToDisk(copy);await ensurePages();$('#noteActionsStatus').textContent='Recovered as an additional section. Your current section is preserved.';scheduleNoteCloud(600)}
