function safeAssetExt(type,name=''){const byName=String(name).match(/\.([A-Za-z0-9]{1,8})$/)?.[1]?.toLowerCase();if(byName)return byName;return({'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/gif':'gif','application/pdf':'pdf'})[type]||'bin'}
function assetCloudName(a){return a.cloudName||`wha2.${a.id}.${safeAssetExt(a.type,a.name)}`}
function currentVisiblePageKey(){const vp=$('#drawingViewport'),els=$$('.paper-segment');if(!vp||!els.length)return activePage?.key||drawPages[0]?.key||'';const vr=vp.getBoundingClientRect(),mid=(vr.top+vr.bottom)/2;let best=null,dist=Infinity;for(const el of els){const r=el.getBoundingClientRect(),cy=(r.top+r.bottom)/2,d=Math.abs(cy-mid);if(d<dist){dist=d;best=el}}return best?.dataset.pageKey||activePage?.key||''}
async function activateVisibleSegment(){const key=currentVisiblePageKey(),hit=pageByKey(key);if(hit?.page._unloaded){const fresh=await noteGet('pages',key);if(fresh)drawPages[hit.index]=fresh}if(key&&activePage?.key!==key)setActivePageByKey(key);return activePage}
async function normalizedImageBlob(file){let bmp=null;try{bmp=await createImageBitmap(file)}catch(_){return{blob:file,width:1600,height:1200,type:file.type||'image/*'}}const ow=bmp.width||1600,oh=bmp.height||1200,max=2600,scale=Math.min(1,max/Math.max(ow,oh));if(scale===1&&file.size<=6*1024*1024)return{blob:file,width:ow,height:oh,type:file.type||'image/*'};const w=Math.max(1,Math.round(ow*scale)),h=Math.max(1,Math.round(oh*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(bmp,0,0,w,h);if(bmp.close)try{bmp.close()}catch(_){}const outType=file.type==='image/png'?'image/png':'image/jpeg',quality=outType==='image/png'?undefined:.91;const blob=await new Promise(res=>c.toBlob(res,outType,quality));return{blob:blob||file,width:w,height:h,type:(blob||file).type||outType}}
async function createAssetFromFile(file,{source='picker'}={}){const id=`a${Date.now().toString(36)}${Math.random().toString(36).slice(2,9)}`;let blob=file,width=0,height=0,type=file.type||'application/octet-stream';if(type.startsWith('image/')){const n=await normalizedImageBlob(file);blob=n.blob;width=n.width;height=n.height;type=n.type}const asset={id,blob,name:file.name||`${source}-${id}`,type,size:blob.size,source,width,height,createdAt:new Date().toISOString(),dirty:true,cloudBackedAt:null};asset.cloudName=assetCloudName(asset);await notePut('assets',asset);return asset}
function defaultInsertRect(asset,ordinal=0){const maxW=CANVAS_W*.72,maxH=CANVAS_H*.56,iw=Number(asset.width)||900,ih=Number(asset.height)||650,scale=Math.min(1,maxW/iw,maxH/ih),w=Math.max(260,iw*scale),h=Math.max(180,ih*scale);return{x:Math.max(60,(CANVAS_W-w)/2+ordinal*28),y:180+ordinal*34,w,h}}
function updateItemTools(){const del=$('#deleteItemBtn'),fit=$('#fitItemBtn'),open=$('#openItemBtn');if(del)del.disabled=!selectedItemId&&!selectedStrokeIds.size;if(fit)fit.disabled=!selectedItemId;if(open)open.disabled=!selectedItemId}
async function insertFiles(files,{source='picker'}={}){const arr=[...files].filter(Boolean);if(!arr.length)return;await activateVisibleSegment();if(!activePage)return;pushUndo();let ordinal=0;for(const f of arr){const asset=await createAssetFromFile(f,{source}),r=defaultInsertRect(asset,ordinal++),z=Date.now()+ordinal;if(asset.type.startsWith('image/')){activePage.images=activePage.images||[];const it={id:`i${asset.id}`,assetId:asset.id,name:asset.name,type:asset.type,...r,rotation:0,opacity:1,z};activePage.images.push(it);selectedItemId=it.id;assetRenderable(asset.id).then(()=>{const c=activeCanvas();if(c)drawPageToCanvas(activePage,c)}).catch(()=>{})}else{activePage.attachments=activePage.attachments||[];const it={id:`f${asset.id}`,assetId:asset.id,name:asset.name,type:asset.type,x:120,y:190+ordinal*34,w:CANVAS_W-240,h:170,z};activePage.attachments.push(it);selectedItemId=it.id}}activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);updateItemTools();await saveActiveDrawing({checkpoint:true,cloud:false});noteStatus(`${arr.length} item${arr.length===1?'':'s'} saved locally · cloud pending`,'dirty');scheduleNoteCloud(900);closeInsertSheet()}
function openInsertSheet(){const s=$('#insertSheet');if(s){s.hidden=false;requestAnimationFrame(()=>s.classList.add('open'))}}
function closeInsertSheet(){const s=$('#insertSheet');if(!s)return;s.classList.remove('open');setTimeout(()=>{if(!s.classList.contains('open'))s.hidden=true},180)}
async function pasteFromClipboard(){try{if(!navigator.clipboard?.read)throw new Error('Clipboard image paste is not supported here');const items=await navigator.clipboard.read(),files=[];for(const item of items){for(const type of item.types||[]){if(type.startsWith('image/')){const b=await item.getType(type);files.push(new File([b],`pasted-${Date.now()}.${safeAssetExt(type)}`,{type}));break}}}if(!files.length)throw new Error('No image found in clipboard');await insertFiles(files,{source:'clipboard'})}catch(e){noteStatus(`${String(e.message||e)} · use Photos`, 'error')}}
function notebookItemAt(p){if(!activePage)return null;const items=pageItems(activePage).slice().reverse();for(const it of items){const x=Number(it.x)||0,y=Number(it.y)||0,w=Number(it.w)||0,h=Number(it.h)||0;if(p.x>=x&&p.x<=x+w&&p.y>=y&&p.y<=y+h)return it}return null}
function findActiveItem(id=selectedItemId){if(!activePage||!id)return null;return (activePage.images||[]).find(x=>x.id===id)||(activePage.attachments||[]).find(x=>x.id===id)||null}
function beginItemGesture(p,item){selectedItemId=item?.id||'';updateItemTools();if(!item){itemGesture=null;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);return}pushUndo();const hr=54,nearResize=Math.hypot(p.x-(item.x+item.w),p.y-(item.y+item.h))<hr;itemGesture={id:item.id,mode:nearResize?'resize':'move',sx:p.x,sy:p.y,x:item.x,y:item.y,w:item.w,h:item.h};const c=activeCanvas();if(c)drawPageToCanvas(activePage,c)}
function moveItemGesture(p){if(!itemGesture)return;const it=findActiveItem(itemGesture.id);if(!it)return;const dx=p.x-itemGesture.sx,dy=p.y-itemGesture.sy;if(itemGesture.mode==='resize'){const ratio=Math.max(.1,itemGesture.w/Math.max(1,itemGesture.h)),nw=Math.max(140,itemGesture.w+dx),nh=Math.max(100,itemGesture.h+dy);if(it.type?.startsWith('image/')){if(Math.abs(dx)>Math.abs(dy))it.w=nw,it.h=nw/ratio;else it.h=nh,it.w=nh*ratio}else{it.w=nw;it.h=nh}}else{it.x=Math.max(-it.w*.7,Math.min(CANVAS_W-it.w*.3,itemGesture.x+dx));it.y=Math.max(-it.h*.7,Math.min(CANVAS_H-it.h*.3,itemGesture.y+dy))}activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c)}
async function endItemGesture(){if(!itemGesture)return;itemGesture=null;if(activePageChanged)await saveActiveDrawing({checkpoint:false})}
async function deleteSelectedItem(){if(!activePage)return;if(selectedStrokeIds.size){pushUndo();activePage.strokes=activePage.strokes.filter(s=>!selectedStrokeIds.has(s.id));selectedStrokeIds.clear();activePageChanged=true;drawPageToCanvas(activePage,activeCanvas());updateItemTools();await saveActiveDrawing({checkpoint:true});return}if(!selectedItemId)return;pushUndo();const id=selectedItemId;activePage.images=(activePage.images||[]).filter(x=>x.id!==id);activePage.attachments=(activePage.attachments||[]).filter(x=>x.id!==id);selectedItemId='';activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);updateItemTools();await saveActiveDrawing({checkpoint:true})}
async function fitSelectedItem(){const it=findActiveItem();if(!it)return;pushUndo();const ratio=Math.max(.1,(Number(it.w)||1)/(Number(it.h)||1));it.w=CANVAS_W-120;it.h=it.w/ratio;if(it.h>CANVAS_H-120){it.h=CANVAS_H-120;it.w=it.h*ratio}it.x=(CANVAS_W-it.w)/2;it.y=60;activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);await saveActiveDrawing({checkpoint:false})}
async function openSelectedItem(){const it=findActiveItem();if(!it)return;const popup=window.open('about:blank','_blank');const a=await noteGet('assets',it.assetId);if(!a?.blob){try{popup?.close()}catch(_){}return}const url=URL.createObjectURL(a.blob);if(popup)popup.location.href=url;else location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60000)}

function emergencyDrawingSnapshot(){if(!activePage||!activePageChanged)return;journalDrawing({...structuredClone(activePage),rev:(Number(activePage.rev)||0)+1,dirty:true,updatedAt:new Date().toISOString()});lastStrokeSafetySaveAt=Date.now()}
function updateCanvasInputMode(){
  const inkTouch=fingerDraw&&drawTool!=='hand';
  for(const c of $$('#infinitePaper canvas')){
    c.classList.toggle('finger-draw',inkTouch);
    c.classList.toggle('select-mode',['select','lasso','text','line','rectangle','ellipse'].includes(drawTool));
    c.classList.toggle('hand-mode',drawTool==='hand');
  }
  const hint=$('#penDetectionState');if(hint)hint.textContent=penDetected?'Active pen detected · palm ignored while writing':fingerDraw?'Touch writing · this pen cannot be separated from your hand':'Pen only · fingers navigate';
  const sb=$('#fingerDrawBtn');if(sb){sb.setAttribute('aria-pressed',String(fingerDraw));sb.textContent=fingerDraw?'✎ Touch: write':'✋ Touch: pan';sb.classList.toggle('active',fingerDraw)}
}
function bindCanvas(c){
  c.addEventListener('pointerdown',e=>{
    if(e.pointerType==='pen'&&drawTool!=='hand')preparePenInput();
    if(drawTool==='hand'||noteGestureLocked||noteTouchPoints.size>1||inkPointerId!==null)return;
    const touchInk=e.pointerType==='touch'&&fingerDraw;
    if(!(e.pointerType==='pen'||e.pointerType==='mouse'||touchInk)||(e.pointerType==='mouse'&&e.button!==0))return;
    if(activePage?.key!==c.dataset.pageKey&&!setActivePageByKey(c.dataset.pageKey))return;
    if(e.pointerType==='pen'){penDetected=true;fingerDraw=false;saveJson(STYLUS_TOUCH_KEY,false);updateCanvasInputMode();$('#penDetectionState').textContent='Active pen detected · fingers only navigate'}
    e.preventDefault();const p=canvasPoint(e,c);inkBefore=pageUndoState();inkBeforeChanged=activePageChanged;inkUndoPushed=false;inkStart=p;
    if(drawTool==='text'){addTextAt(p).catch(err=>noteStatus(String(err),'error'));return}
    drawing=true;inkPointerType=e.pointerType;inkPointerId=e.pointerId;try{c.setPointerCapture?.(e.pointerId)}catch(_){};lastStrokeSafetySaveAt=Date.now();
    if(drawTool==='select'){const it=notebookItemAt(p);beginItemGesture(p,it);inkUndoPushed=!!it;return}
    if(drawTool==='lasso'){
      const b=strokeSelectionBounds();if(b&&p.x>=b.x-18&&p.x<=b.x+b.w+18&&p.y>=b.y-18&&p.y<=b.y+b.h+18){pushUndo();inkUndoPushed=true;strokeMove={start:p,original:structuredClone(activePage.strokes)}}else{selectedStrokeIds.clear();lassoPath=[p];strokeMove=null}drawPageToCanvas(activePage,c);return
    }
    pushUndo();inkUndoPushed=true;activePageChanged=true;
    if(drawTool==='eraser'){eraseAt(p);liveStroke=null}
    else{liveStroke={id:`s${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`,tool:drawTool,color:drawColor,width:drawWidth,points:[p]};activePage.strokes.push(liveStroke);drawPageToCanvas(activePage,c)}
  },{passive:false});
  c.addEventListener('pointermove',e=>{
    if(!drawing||e.pointerId!==inkPointerId||!activePage||activePage.key!==c.dataset.pageKey||noteGestureLocked)return;
    e.preventDefault();const coalesced=typeof e.getCoalescedEvents==='function'?e.getCoalescedEvents():[],events=coalesced.length?coalesced:[e],p=canvasPoint(events[events.length-1],c);
    if(drawTool==='select'){moveItemGesture(p);return}
    if(drawTool==='lasso'){if(strokeMove){activePage.strokes=strokeMove.original.map(st=>selectedStrokeIds.has(st.id)?{...st,points:st.points.map(pt=>({...pt,x:pt.x+p.x-strokeMove.start.x,y:pt.y+p.y-strokeMove.start.y}))}:st);activePageChanged=true}else lassoPath.push(p);drawPageToCanvas(activePage,c);return}
    if(['line','rectangle','ellipse'].includes(drawTool)&&liveStroke){liveStroke.points=shapePoints(drawTool,inkStart,p);activePageChanged=true;drawPageToCanvas(activePage,c)}
    else for(const ev of events){const pt=canvasPoint(ev,c);if(drawTool==='eraser')eraseAt(pt);else if(liveStroke){const last=liveStroke.points[liveStroke.points.length-1];if(Math.hypot(pt.x-last.x,pt.y-last.y)>.65){liveStroke.points.push(pt);activePageChanged=true;drawStroke(c.getContext('2d'),{...liveStroke,points:[last,pt]})}}}
    if(activePageChanged&&Date.now()-lastStrokeSafetySaveAt>1500)emergencyDrawingSnapshot()
  },{passive:false});
  const end=async e=>{if(!drawing||e.pointerId!==inkPointerId||activePage?.key!==c.dataset.pageKey)return;drawing=false;inkPointerId=null;try{c.releasePointerCapture?.(e.pointerId)}catch(_){}
    if(e.pointerType==='pen')lastPenInputAt=performance.now();
    if(drawTool==='lasso'){if(!strokeMove&&lassoPath.length>2){for(const st of activePage.strokes||[])if((st.points||[]).some(pt=>pointInLasso(pt,lassoPath)))selectedStrokeIds.add(st.id)}strokeMove=null;lassoPath=[];updateItemTools();drawPageToCanvas(activePage,c)}
    if(drawTool==='select')itemGesture=null;liveStroke=null;await saveActiveDrawing({checkpoint:false});maybeGrowInfinitePaper().catch(()=>{})};
  for(const type of ['pointerup','pointercancel','lostpointercapture'])c.addEventListener(type,e=>end(e).catch(err=>noteStatus(String(err.message||err),'error')),{passive:false});
  c.addEventListener('dblclick',e=>{if(drawTool!=='select')return;if(activePage?.key!==c.dataset.pageKey&&!setActivePageByKey(c.dataset.pageKey))return;const it=notebookItemAt(canvasPoint(e,c));if(it){selectedItemId=it.id;updateItemTools();if(it.kind==='text'){const text=prompt('Edit text',it.text||it.name);if(text!==null){pushUndo();Object.assign(findActiveItem(it.id),{text,name:text});activePageChanged=true;drawPageToCanvas(activePage,c);saveActiveDrawing().catch(()=>{})}}else openSelectedItem().catch(()=>{})}})
}
