function undoDrawing(){if(!activePage||!undoStack.length)return;redoStack.push(pageUndoState());applyUndoState(undoStack.pop());selectedItemId='';activePageChanged=true;const c=activeCanvas();if(c)drawPageToCanvas(activePage,c);updateItemTools();saveActiveDrawing({checkpoint:false})}
