function timerRemaining(){return timer.running?Math.max(0,timer.endAt-Date.now()):Math.max(0,timer.remainingMs||0)}
function renderTimer(){const live=remoteIsFresh();if(live){const s=remoteLive.study||{},el=$('#timerText'),btn=$('#timerToggle');if(el)el.textContent=remoteTime(remoteRemaining());if(btn)btn.textContent=s.running?'Pause':'Start';return}const r=timerRemaining(),s=Math.ceil(r/1000),m=Math.floor(s/60),ss=s%60;const el=$('#timerText'),btn=$('#timerToggle');if(el)el.textContent=`${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;if(btn)btn.textContent=timer.running?'Pause':'Start';if(timer.running&&r<=0){timer={remainingMs:10*60*1000,running:false,endAt:0};saveJson(TIMER_KEY,timer)}}
