async function storeTokens(tok){let loginHint='';try{const payload=JSON.parse(atob(tok.id_token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));loginHint=payload.preferred_username||payload.email||''}catch(_){}const cur=await authGet('tokens')||{};await authSet('tokens',{...cur,...tok,login_hint:loginHint||cur.login_hint||'',expires_at:Date.now()+Math.max(60,Number(tok.expires_in||3600)-60)*1000})}
async function accessToken(){if(notesAuthRefresh)return notesAuthRefresh;notesAuthRefresh=(async()=>{const t=await authGet('tokens');if(t?.access_token&&Date.now()<Number(t.expires_at||0))return t.access_token;if(t?.refresh_token){cfg=loadJson(CFG_KEY,cfg);const body=new URLSearchParams({client_id:cfg.clientId||DEFAULT_MS_CLIENT_ID,grant_type:'refresh_token',refresh_token:t.refresh_token,redirect_uri:redirectUri(),scope:AUTH_SCOPES});const r=await fetch(`https://login.microsoftonline.com/${encodeURIComponent(cfg.tenant||'common')}/oauth2/v2.0/token`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const j=await r.json();if(r.ok){await storeTokens(j);return j.access_token}if(j.error==='invalid_grant'||j.error==='interaction_required'){await authSet('tokens',{...t,access_token:'',refresh_token:'',expires_at:0});setNotesConnection('auth')}}return null})();try{return await notesAuthRefresh}finally{notesAuthRefresh=null}}
async function graph(url,opts={}){let token=await accessToken();if(!token){setNotesConnection('auth');throw new Error('Reconnect Microsoft to sync notes')}const full=/^https?:/i.test(url)?url:`https://graph.microsoft.com/v1.0${url}`,send=()=>fetch(full,{...opts,headers:{Authorization:`Bearer ${token}`,...(opts.headers||{})}});let response=await send();if(response.status===401){const t=await authGet('tokens');if(t)await authSet('tokens',{...t,expires_at:0});token=await accessToken();if(!token){setNotesConnection('auth');throw new Error('Reconnect Microsoft to sync notes')}response=await send();if(response.status===401){setNotesConnection('auth');throw new Error('OneDrive sign-in expired. Reconnect Microsoft.')}}return response}
