function rootFolderParts(){return String(cfg.folder||'').split('/').filter(Boolean)}
function legacyGraphFilePath(){return `/me/drive/root:/${graphPath([...rootFolderParts(),FILE_NAME])}:/content`}
function deviceFileName(){return `device-${String(meta.deviceId||'mobile').replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,96)}.json`}
