async function ensureSyncDeviceFolder(){const parts=rootFolderParts(),parent=`/me/drive/root:/${graphPath(parts)}:/children`,target=`/me/drive/root:/${graphPath([...parts,DEVICE_DIR])}`;let r=await graph(target);if(r.ok)return;if(r.status!==404)throw new Error(`Sync folder check failed (${r.status})`);r=await graph(parent,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:DEVICE_DIR,folder:{},'@microsoft.graph.conflictBehavior':'fail'})});if(!r.ok&&r.status!==409)throw new Error(`Could not create conflict-safe sync folder (${r.status})`)}
