async function writeDeviceCloud(payload){await ensureSyncDeviceFolder();const r=await graph(deviceGraphFilePath(),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error(`OneDrive device write failed (${r.status})`);return r.json().catch(()=>null)}
async function syncNow(){cfg=loadJson(CFG_KEY,cfg);$('#syncNowBtn').disabled=true;renderStatus({text:'OneDrive: conflict-safe syncing…'});try{const snapshots=await fetchCloudSnapshots(),local=state||{};let merged=local,clocks={...(meta.clocks||{})};for(const remote of snapshots){const res=merge(merged,remote.warriorState||{},clocks,remote.clocks||{},remote.updatedAt||0);merged=res.state;clocks=res.clocks}state=merged;meta.clocks=clocks;const own=snapshots.find(x=>String(x.deviceId||'')===String(meta.deviceId||''));const changed=!own||JSON.stringify(state)!==JSON.stringify(own.warriorState||{})||JSON.stringify(meta.clocks)!==JSON.stringify(own.clocks||{});let payload=own||null;if(changed){payload={schema:SCHEMA,app:'Warrior Hub',syncMode:'device-shard-v1',version:`mobile-${APP_VERSION}`,updatedAt:Date.now(),deviceId:meta.deviceId,clocks:meta.clocks,warriorState:state};await writeDeviceCloud(payload)}if(!payload)payload={schema:SCHEMA,app:'Warrior Hub',version:`mobile-${APP_VERSION}`,updatedAt:Date.now(),deviceId:meta.deviceId,clocks:meta.clocks,warriorState:state};cloud=payload;meta.lastSyncAt=Date.now();meta.shardedSync=true;saveLocalCloud();renderAll();renderStatus({kind:'ok',text:`OneDrive conflict-safe sync · ${state.assignments?.length||0} assignments`});flushDrawingCloud().catch(e=>log('drawing-backup-after-sync',{error:String(e)}));log('sync-success',{changed,updatedAt:payload.updatedAt,snapshotCount:snapshots.length,deviceFile:deviceFileName()})}catch(e){log('sync-error',{error:String(e.message||e)});renderStatus({kind:'error',text:String(e.message||e)})}finally{$('#syncNowBtn').disabled=false}}
